import { useParams } from "react-router-dom";
import React, { useState, useEffect, useCallback } from "react";
import axios from "axios";
import styled from "styled-components";
import DatePicker from "react-datepicker";
import "react-datepicker/dist/react-datepicker.css";

const FuelPage = () => {
  const { lorryId } = useParams(); // Get lorryId from the URL
  const [fuelDetails, setFuelDetails] = useState([]);
  const [fuelData, setFuelData] = useState({
    fuel_date: "",
    bunk_name: "",
    total_amount: "",
    amount_paid: "",
  });
  const [startDate, setStartDate] = useState(null);
  const [endDate, setEndDate] = useState(null);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFuelData({ ...fuelData, [name]: value });
  };

  const handleDateChange = (date, type) => {
    if (type === "start") {
      setStartDate(date);
    } else {
      setEndDate(date);
    }
  };

  const addFuel = async () => {
    if (!fuelData.fuel_date || !fuelData.bunk_name || !fuelData.total_amount || !fuelData.amount_paid) {
      alert("Please fill all fields correctly.");
      return;
    }

    try {
      const totalAmount = parseFloat(fuelData.total_amount);
      const amountPaid = parseFloat(fuelData.amount_paid);

      if (isNaN(totalAmount) || isNaN(amountPaid)) {
        alert("Total amount and Amount paid must be valid numbers.");
        return;
      }

      await axios.post("http://localhost:5001/api/fuel/add", {
        fuel_date: fuelData.fuel_date,
        bunk_name: fuelData.bunk_name,
        total_amount: totalAmount,
        amount_paid: amountPaid,
      });

      alert("Fuel details added successfully");
      setFuelData({ fuel_date: "", bunk_name: "", total_amount: "", amount_paid: "" });
    } catch (error) {
      console.error("Error adding fuel", error);
      alert("Error adding fuel. Please check the input values.");
    }
  };

  const fetchFuelDetails = useCallback(async () => {
    try {
      const response = await axios.get(`http://localhost:5001/api/fuel/${lorryId}`, {
        params: {
          startDate: startDate?.toISOString().split("T")[0], // Format date as YYYY-MM-DD
          endDate: endDate?.toISOString().split("T")[0],
        },
      });
      setFuelDetails(response.data);
    } catch (error) {
      console.error("Error fetching fuel details", error);
    }
  }, [lorryId, startDate, endDate]);

  useEffect(() => {
    if (startDate && endDate) {
      fetchFuelDetails();
    }
  }, [fetchFuelDetails]);

  return (
    <Container>
      <LorryId>{`Lorry ID: ${lorryId}`}</LorryId>

      <Section>
        <h3>Add Fuel Details</h3>
        <Form>
          <input
            type="date"
            name="fuel_date"
            value={fuelData.fuel_date}
            onChange={handleChange}
            required
          />
          <input
            type="text"
            name="bunk_name"
            placeholder="Bunk Name"
            value={fuelData.bunk_name}
            onChange={handleChange}
            required
          />
          <input
            type="number"
            name="total_amount"
            placeholder="Total Amount"
            value={fuelData.total_amount}
            onChange={handleChange}
            required
          />
          <input
            type="number"
            name="amount_paid"
            placeholder="Amount Paid"
            value={fuelData.amount_paid}
            onChange={handleChange}
            required
          />
          <button type="button" onClick={addFuel}>Add Fuel</button>
        </Form>
      </Section>

      <Section>
        <h3>Filter by Date Range</h3>
        <DateContainer>
          <DatePicker
            selected={startDate}
            onChange={(date) => handleDateChange(date, "start")}
            selectsStart
            startDate={startDate}
            endDate={endDate}
            dateFormat="dd/MM/yyyy"
            placeholderText="Start Date"
          />
          <DatePicker
            selected={endDate}
            onChange={(date) => handleDateChange(date, "end")}
            selectsEnd
            startDate={startDate}
            endDate={endDate}
            minDate={startDate}
            dateFormat="dd/MM/yyyy"
            placeholderText="End Date"
          />
          <button onClick={fetchFuelDetails}>Fetch Fuel Details</button>
        </DateContainer>
      </Section>

      <Section>
        <h3>Fuel Details</h3>
        <Table>
          <thead>
            <tr>
              <th>Fuel Date</th>
              <th>Bunk Name</th>
              <th>Total Amount</th>
              <th>Amount Paid</th>
              <th>Remaining Amount</th>
            </tr>
          </thead>
          <tbody>
            {fuelDetails.map((fuel) => (
              <tr key={fuel.id}>
                <td>{fuel.fuel_date}</td>
                <td>{fuel.bunk_name}</td>
                <td>{fuel.total_amount}</td>
                <td>{fuel.amount_paid}</td>
                <td>{(fuel.total_amount - fuel.amount_paid).toFixed(2)}</td>
              </tr>
            ))}
          </tbody>
        </Table>
      </Section>
    </Container>
  );
};

const Container = styled.div`
  padding: 20px;
  max-width: 1200px;
  margin: 0 auto;
`;

const LorryId = styled.h2`
  text-align: center;
  margin-bottom: 20px;
`;

const Section = styled.div`
  margin-bottom: 30px;
`;

const Form = styled.div`
  display: grid;
  gap: 10px;
  max-width: 400px;
  margin: 0 auto;

  input {
    padding: 10px;
    font-size: 14px;
    border: 1px solid #ddd;
    border-radius: 5px;
  }

  button {
    padding: 10px;
    font-size: 16px;
    background-color: #007bff;
    color: white;
    border: none;
    border-radius: 5px;
    cursor: pointer;
    &:hover {
      background-color: #0056b3;
    }
  }
`;

const DateContainer = styled.div`
  display: flex;
  gap: 20px;
  justify-content: center;
  margin-bottom: 20px;

  button {
    padding: 10px;
    background-color: #007bff;
    color: white;
    border: none;
    border-radius: 5px;
    cursor: pointer;
    &:hover {
      background-color: #0056b3;
    }
  }
`;

const Table = styled.table`
  width: 100%;
  border-collapse: collapse;
  margin-top: 20px;

  th, td {
    padding: 12px;
    text-align: center;
    border: 1px solid #ddd;
  }

  th {
    background-color: #f4f4f4;
  }

  tr:nth-child(even) {
    background-color: #f9f9f9;
  }
`;

export default FuelPage;
